/****************************************************************************
 * app/velaguard/vg_device_id.h
 *
 * Stable MQTT / topic identity: vg- + STM32 96-bit UID hex.
 * Compile-time CONFIG_VG_MQTT_DEVICE_ID or DEVID overrides (host / test).
 ****************************************************************************/

#ifndef __VG_DEVICE_ID_H
#define __VG_DEVICE_ID_H

#include <stddef.h>
#include <stdint.h>

#define VG_DEVICE_UID_LEN 12
#define VG_DEVICE_ID_MAX  32

int vg_device_id_read_uid(uint8_t uid[VG_DEVICE_UID_LEN]);

int vg_device_id_from_uid(const uint8_t uid[VG_DEVICE_UID_LEN],
                          char *out, size_t n);

/* Cached. First call reads UID (or applies override). Never returns NULL. */
const char *vg_device_id(void);

#endif

/****************************************************************************
 * app/velaguard/vg_device_id.c
 *
 * device_id / MQTT client_id: vg- + 24 lowercase hex of the 96-bit UID.
 ****************************************************************************/

#include "vg_device_id.h"

#include <stdio.h>
#include <string.h>

int vg_device_id_read_uid(uint8_t uid[VG_DEVICE_UID_LEN])
{
  if (uid == NULL)
    {
      return -1;
    }

#ifdef __NuttX__
  memcpy(uid, (const volatile void *)0x1ff1e800, VG_DEVICE_UID_LEN);
#else
  memset(uid, 0xab, VG_DEVICE_UID_LEN);
#endif
  return 0;
}

int vg_device_id_from_uid(const uint8_t uid[VG_DEVICE_UID_LEN],
                          char *out, size_t n)
{
  int i;
  int off;

  if (uid == NULL || out == NULL || n < 4)
    {
      return -1;
    }

  off = snprintf(out, n, "vg-");
  if (off < 0 || (size_t)off >= n)
    {
      return -1;
    }

  for (i = 0; i < VG_DEVICE_UID_LEN; i++)
    {
      int w = snprintf(out + off, n - (size_t)off, "%02x", uid[i]);
      if (w != 2)
        {
          return -1;
        }

      off += 2;
    }

  return 0;
}

const char *vg_device_id(void)
{
  static char id[VG_DEVICE_ID_MAX];
  static int ready;
  uint8_t uid[VG_DEVICE_UID_LEN];

  if (ready)
    {
      return id;
    }

#ifdef CONFIG_VG_MQTT_DEVICE_ID
  if (CONFIG_VG_MQTT_DEVICE_ID[0] != '\0')
    {
      snprintf(id, sizeof(id), "%s", CONFIG_VG_MQTT_DEVICE_ID);
      ready = 1;
      return id;
    }
#endif

#ifdef DEVID
  snprintf(id, sizeof(id), "%s", DEVID);
  ready = 1;
  return id;
#else
  if (vg_device_id_read_uid(uid) != 0 ||
      vg_device_id_from_uid(uid, id, sizeof(id)) != 0)
    {
      snprintf(id, sizeof(id), "vg-unknown");
    }

  ready = 1;
  return id;
#endif
}

/****************************************************************************
 * app/velaguard/vg_mqtt_payload.h
 *
 * Host-testable JSON / topic helpers for dashboard-api v1 board publish.
 ****************************************************************************/

#ifndef __VG_MQTT_PAYLOAD_H
#define __VG_MQTT_PAYLOAD_H

#include <stddef.h>
#include <stdint.h>

#define VG_MQTT_TOPIC_MAX 64

struct vg_mqtt_tel_pt
{
  const char *id;
  float value;
  int ok;
  uint32_t age_ms;
};

int vg_mqtt_topic(char *out, size_t n, const char *device_id,
                  const char *kind);

int vg_mqtt_format_lwt(char *out, size_t n, const char *device_id);

int vg_mqtt_format_status(char *out, size_t n, const char *device_id,
                          const char *network, long long uptime_ms,
                          long long ts_ms);

int vg_mqtt_format_telemetry(char *out, size_t n,
                             const struct vg_mqtt_tel_pt *pts, int npt);

const char *vg_mqtt_alarm_kind(int is_offline, const char *cmp);

int vg_mqtt_format_alarm(char *out, size_t n, const char *device_id,
                         const char *alarm_id, const char *point_id,
                         const char *kind, const char *state, float value,
                         float thr, const char *level, long long ts_ms);

int vg_mqtt_point_table_has_points(const char *json, size_t len);

#endif

/****************************************************************************
 * app/velaguard/vg_mqtt_payload.c
 *
 * UTF-8 JSON skeletons for dashboard-api board publish. No MQTT-C.
 ****************************************************************************/

#include "vg_mqtt_payload.h"

#include <stdio.h>
#include <string.h>

static int appendf(char *out, size_t n, int off, const char *fmt, ...)
{
  va_list ap;
  int w;

  if (off < 0 || (size_t)off >= n)
    {
      return -1;
    }

  va_start(ap, fmt);
  w = vsnprintf(out + off, n - (size_t)off, fmt, ap);
  va_end(ap);
  if (w < 0 || (size_t)off + (size_t)w >= n)
    {
      return -1;
    }

  return off + w;
}

int vg_mqtt_topic(char *out, size_t n, const char *device_id,
                  const char *kind)
{
  if (out == NULL || n == 0 || device_id == NULL || kind == NULL ||
      device_id[0] == '\0' || kind[0] == '\0')
    {
      return -1;
    }

  if (snprintf(out, n, "vg/%s/%s", device_id, kind) >= (int)n)
    {
      return -1;
    }

  return 0;
}

int vg_mqtt_format_lwt(char *out, size_t n, const char *device_id)
{
  if (out == NULL || device_id == NULL || device_id[0] == '\0')
    {
      return -1;
    }

  if (snprintf(out, n, "{\"device_id\":\"%s\",\"online\":false}",
               device_id) >= (int)n)
    {
      return -1;
    }

  return 0;
}

int vg_mqtt_format_status(char *out, size_t n, const char *device_id,
                          const char *network, long long uptime_ms,
                          long long ts_ms)
{
  if (out == NULL || device_id == NULL || device_id[0] == '\0')
    {
      return -1;
    }

  if (network == NULL || network[0] == '\0')
    {
      network = "none";
    }

  if (snprintf(out, n,
               "{\"device_id\":\"%s\",\"online\":true,"
               "\"firmware\":\"0.1.0\",\"build_mode\":\"TEST\","
               "\"network\":\"%s\",\"uptime_ms\":%lld,\"ts_ms\":%lld,"
               "\"time_quality\":\"unknown\"}",
               device_id, network, uptime_ms, ts_ms) >= (int)n)
    {
      return -1;
    }

  return 0;
}

int vg_mqtt_format_telemetry(char *out, size_t n,
                             const struct vg_mqtt_tel_pt *pts, int npt)
{
  int i;
  int off;

  if (out == NULL || n < 3)
    {
      return -1;
    }

  if (pts == NULL || npt <= 0)
    {
      snprintf(out, n, "[]");
      return 0;
    }

  off = snprintf(out, n, "[");
  for (i = 0; i < npt; i++)
    {
      const struct vg_mqtt_tel_pt *p = &pts[i];
      const char *id = (p->id && p->id[0]) ? p->id : "-";

      if (i > 0)
        {
          off = appendf(out, n, off, ",");
          if (off < 0)
            {
              return -1;
            }
        }

      if (p->ok)
        {
          off = appendf(out, n, off,
                        "{\"id\":\"%s\",\"value\":%.6g,\"ok\":true,"
                        "\"age_ms\":%u}",
                        id, (double)p->value, (unsigned)p->age_ms);
        }
      else
        {
          off = appendf(out, n, off,
                        "{\"id\":\"%s\",\"value\":null,\"ok\":false,"
                        "\"age_ms\":%u}",
                        id, (unsigned)p->age_ms);
        }

      if (off < 0)
        {
          return -1;
        }
    }

  off = appendf(out, n, off, "]");
  return (off < 0) ? -1 : 0;
}

const char *vg_mqtt_alarm_kind(int is_offline, const char *cmp)
{
  if (is_offline)
    {
      return "offline";
    }

  if (cmp != NULL && strcmp(cmp, "le") == 0)
    {
      return "threshold_low";
    }

  return "threshold_high";
}

int vg_mqtt_format_alarm(char *out, size_t n, const char *device_id,
                         const char *alarm_id, const char *point_id,
                         const char *kind, const char *state, float value,
                         float thr, const char *level, long long ts_ms)
{
  int off;

  if (out == NULL || device_id == NULL || point_id == NULL || kind == NULL ||
      state == NULL || device_id[0] == '\0' || point_id[0] == '\0')
    {
      return -1;
    }

  off = snprintf(out, n,
                 "{\"ts\":%lld,\"device_id\":\"%s\"",
                 ts_ms, device_id);
  if (off < 0 || (size_t)off >= n)
    {
      return -1;
    }

  if (alarm_id != NULL && alarm_id[0] != '\0')
    {
      off = appendf(out, n, off, ",\"alarm_id\":\"%s\"", alarm_id);
      if (off < 0)
        {
          return -1;
        }
    }

  off = appendf(out, n, off,
                ",\"id\":\"%s\",\"kind\":\"%s\",\"value\":%.6g,\"thr\":%.6g,"
                "\"state\":\"%s\"",
                point_id, kind, (double)value, (double)thr, state);
  if (off < 0)
    {
      return -1;
    }

  if (level != NULL && level[0] != '\0')
    {
      off = appendf(out, n, off, ",\"level\":\"%s\"", level);
      if (off < 0)
        {
          return -1;
        }
    }

  off = appendf(out, n, off, "}");
  return (off < 0) ? -1 : 0;
}

int vg_mqtt_point_table_has_points(const char *json, size_t len)
{
  const char *p;
  const char *end;
  const char *arr;

  if (json == NULL || len == 0)
    {
      return 0;
    }

  end = json + len;
  arr = strstr(json, "\"points\"");
  if (arr == NULL || arr >= end)
    {
      return 0;
    }

  p = strchr(arr, '[');
  if (p == NULL || p >= end)
    {
      return 0;
    }

  for (p++; p < end; p++)
    {
      if (*p == ' ' || *p == '\n' || *p == '\r' || *p == '\t')
        {
          continue;
        }

      return (*p != ']');
    }

  return 0;
}

