static void drain_queues(void)
{
  char alarm_copy[VG_MQTT_ALARM_B];
  int send_pt;
  int send_tel;

  for (; ; )
    {
      alarm_copy[0] = '\0';
      pthread_mutex_lock(&g_qlock);
      if (g_alarm_count > 0)
        {
          struct vg_mqtt_alarm_slot *s = &g_alarm_q[g_alarm_head];

          snprintf(alarm_copy, sizeof(alarm_copy), "%s", s->json);
          s->used = 0;
          g_alarm_head = (g_alarm_head + 1) % VG_MQTT_ALARM_N;
          g_alarm_count--;
        }

      pthread_mutex_unlock(&g_qlock);
      if (alarm_copy[0] == '\0')
        {
          break;
        }

      if (publish_raw("alarm", alarm_copy, strlen(alarm_copy),
                      MQTT_PUBLISH_QOS_1) != 0)
        {
          /* Put it back at the head if publish failed. */
