  node = (FAR struct mm_freenode_s *)
         ((FAR char *)kasan_clear_tag(mem) - MM_SIZEOF_ALLOCNODE);
  nodesize = MM_SIZEOF_NODE(node);
  if (nodesize < MM_MIN_CHUNK ||
      !mm_heapmember(heap, (FAR char *)node + nodesize - 1))
    {
      serr("ERROR: mm_forcefree %p node=%p size=%zu corrupt, leaked\n",
           mem, node, nodesize);
      return;
    }

